const entrada = $input.first().json;
const cuerpo = entrada.body;
const falla = (estado, codigo, mensaje, detalles) => ({
  ok: false, estado,
  cuerpo: { error: { codigo, mensaje, ...(detalles ? { detalles } : {}) } },
});
const ESPERADOS = ['correo', 'nombre', 'contrasena'];

if (cuerpo === null || typeof cuerpo !== 'object' || Array.isArray(cuerpo)) {
  return [{ json: falla(422, 'VALIDACION_FALLIDA', 'La solicitud no es válida.', [
    { campo: 'cuerpo', regla: 'debe_ser_objeto', mensaje: 'El cuerpo debe ser un objeto JSON.' },
  ]) }];
}

const detalles = [];
for (const clave of Object.keys(cuerpo)) {
  if (!ESPERADOS.includes(clave)) {
    detalles.push({ campo: clave.slice(0, 40), regla: 'campo_no_permitido', mensaje: 'Este campo no está permitido.' });
  }
}
for (const campo of ESPERADOS) {
  if (!(campo in cuerpo)) detalles.push({ campo, regla: 'obligatorio', mensaje: 'Este campo es obligatorio.' });
  else if (typeof cuerpo[campo] !== 'string') detalles.push({ campo, regla: 'debe_ser_texto', mensaje: 'Debe ser un texto.' });
}

const correo = typeof cuerpo.correo === 'string' ? cuerpo.correo.trim().toLowerCase() : '';
const nombre = typeof cuerpo.nombre === 'string' ? cuerpo.nombre.trim() : '';
const contrasena = typeof cuerpo.contrasena === 'string' ? cuerpo.contrasena : '';

if (typeof cuerpo.correo === 'string') {
  const formato = /^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$/;
  const local = correo.split('@')[0] || '';
  if (correo.length === 0 || correo.length > 254 || local.length > 64 || !formato.test(correo)) {
    detalles.push({ campo: 'correo', regla: 'formato_invalido', mensaje: 'Debe ser un correo válido de hasta 254 caracteres.' });
  }
}
if (typeof cuerpo.nombre === 'string') {
  const largo = [...nombre].length;
  if (largo < 1 || largo > 80) {
    detalles.push({ campo: 'nombre', regla: 'largo_invalido', mensaje: 'Debe tener entre 1 y 80 caracteres.' });
  } else if (/[\u0000-\u001F\u007F-\u009F]/.test(nombre)) {
    detalles.push({ campo: 'nombre', regla: 'caracteres_de_control', mensaje: 'No puede tener caracteres de control.' });
  }
}

if (detalles.length > 0) {
  return [{ json: falla(422, 'VALIDACION_FALLIDA', 'La solicitud no es válida.', detalles) }];
}

// Política de contraseña (todas las reglas fallidas se devuelven juntas)
const reglas = [];
const falloRegla = (regla, mensaje) => reglas.push({ campo: 'contrasena', regla, mensaje });
if ([...contrasena].length < 12) falloRegla('minimo_12_caracteres', 'Debe tener al menos 12 caracteres.');
if (Buffer.byteLength(contrasena, 'utf8') > 72) falloRegla('maximo_72_bytes', 'No puede superar 72 bytes en UTF-8.');
if (!/\p{Lu}/u.test(contrasena)) falloRegla('requiere_mayuscula', 'Debe incluir al menos una mayúscula.');
if (!/\p{Ll}/u.test(contrasena)) falloRegla('requiere_minuscula', 'Debe incluir al menos una minúscula.');
if (!/\p{N}/u.test(contrasena)) falloRegla('requiere_numero', 'Debe incluir al menos un número.');
if (!/[^\p{L}\p{N}\s]/u.test(contrasena)) falloRegla('requiere_simbolo', 'Debe incluir al menos un símbolo.');
if (contrasena !== contrasena.trim()) falloRegla('sin_espacios_extremos', 'No puede empezar ni terminar con espacios.');
const minuscula = contrasena.toLowerCase();
const parteLocal = correo.split('@')[0];
if (minuscula.includes(correo) || (parteLocal.length >= 4 && minuscula.includes(parteLocal))) {
  falloRegla('no_contiene_correo', 'No puede contener tu correo ni su parte local.');
}

const candidatas = [minuscula];
const sinFinal = minuscula.replace(/[\d\W_]+$/u, '');
if (sinFinal && sinFinal !== minuscula) candidatas.push(sinFinal);

return [{ json: { ok: true, correo, nombre, contrasena, reglas_fallidas: reglas, candidatas_comunes: candidatas } }];

const solicitud = $('Validar solicitud').first().json;
const consulta = $input.first().json;
if (consulta.error || typeof consulta.es_comun !== 'boolean') {
  return [{ json: { ok: false, estado: 500, cuerpo: { error: { codigo: 'ERROR_INTERNO', mensaje: 'Error interno del servidor.' } } } }];
}
const detalles = [...solicitud.reglas_fallidas];
if (consulta.es_comun) {
  detalles.push({ campo: 'contrasena', regla: 'no_es_comun', mensaje: 'Es una contraseña demasiado común.' });
}
if (detalles.length > 0) {
  return [{ json: { ok: false, estado: 422, cuerpo: { error: { codigo: 'CONTRASENA_INSEGURA', mensaje: 'La contraseña no cumple los requisitos.', detalles } } } }];
}
return [{ json: { ok: true } }];

const respuesta = $input.first().json;
const estado = respuesta.statusCode;
const cuerpoAuth = respuesta.body && typeof respuesta.body === 'object' ? respuesta.body : {};
const creada = { estado: 201, cuerpo: { mensaje: 'Cuenta creada. Ya puedes iniciar sesión.' } };

if (estado >= 200 && estado < 300) return [{ json: creada }];
// Correo ya registrado: misma respuesta que una cuenta nueva (no revela qué correos existen)
if (['user_already_exists', 'email_exists'].includes(cuerpoAuth.error_code)) return [{ json: creada }];
if (estado === 400 || estado === 422) {
  return [{ json: { estado: 422, cuerpo: { error: { codigo: 'VALIDACION_FALLIDA', mensaje: 'La solicitud no es válida.', detalles: [
    { campo: 'correo', regla: 'rechazado', mensaje: 'El correo no fue aceptado.' },
  ] } } } }];
}
if (estado === 429) {
  return [{ json: { estado: 429, cuerpo: { error: { codigo: 'DEMASIADOS_INTENTOS', mensaje: 'Demasiadas solicitudes. Inténtalo más tarde.' } } } }];
}
return [{ json: { estado: 500, cuerpo: { error: { codigo: 'ERROR_INTERNO', mensaje: 'Error interno del servidor.' } } } }];
